// ПРОД: только просмотр. «התנתקות» / «יציאה מהחשבון» не нажимать.
import { test, expect } from '../../fixtures';

test.describe('Админка контента молитв (/admin)', () => {
  test('AD-02 Профиль: у админа «ניהול ← ממשק ניהול התוכן» открывает админку; у user1 строки нет #a5decf4a @prod-safe @mobile', async ({ asUser }) => {
    // 1. admin: /profile → раздел «ניהול» → «ממשק ניהול התוכן».
    const admin = await asUser('admin');
    await admin.goto('/profile');
    const entry = admin.getByText('ממשק ניהול התוכן', { exact: true });
    await expect(entry).toBeVisible({ timeout: 20_000 });
    await expect(admin.getByText('ניהול', { exact: true })).toBeVisible();
    await expect(admin.getByText('מנהל תוכן', { exact: true }).first()).toBeVisible();
    await entry.click();
    await expect(admin.getByText('ניהול תכני תפילה')).toBeVisible({ timeout: 20_000 });
    await expect(admin).toHaveURL(/\/admin/);

    // 2. user1: /profile — строки «ממשק ניהול התוכן» нет.
    const user = await asUser('user1');
    await user.goto('/profile');
    await expect(user.getByText('אודות', { exact: true })).toBeVisible({ timeout: 20_000 });
    await expect(user.getByText('ממשק ניהול התוכן')).toHaveCount(0);
  });
});
